static int32_t ui_demo_wifi_signal_from_rssi(int32_t rssi)
{
  if (rssi == 0)
    {
      return 0;
    }

  if (rssi >= -35)
    {
      return 100;
    }

  if (rssi <= -95)
    {
      return 5;
    }

  return 5 + ((rssi + 95) * 95) / 60;
}

